type settingsIntegrationReplacement struct {
	english string
	id      string
}

var settingsIntegrationReplacements []settingsIntegrationReplacement

func init() {
	Register("settings.integrations", settingsIntegrationsEnglish, settingsIntegrationsSpanish)
	settingsIntegrationReplacements = make([]settingsIntegrationReplacement, 0, len(settingsIntegrationsEnglish))
	for id, english := range settingsIntegrationsEnglish {
		if strings.Contains(english, "%") {
			continue
		}
		settingsIntegrationReplacements = append(settingsIntegrationReplacements, settingsIntegrationReplacement{
			english: english,
			id:      id,
		})
	}
	sort.Slice(settingsIntegrationReplacements, func(i, j int) bool {
		return len(settingsIntegrationReplacements[i].english) > len(settingsIntegrationReplacements[j].english)
	})
}

// SettingsIntegrationsText localizes TUI-owned chrome after nested settings
// renderers have composed it. Canonical names, IDs, commands, state tokens, and
// external descriptions are not catalog entries and therefore remain unchanged.
func SettingsIntegrationsText(text string) string {
	if CurrentLanguage() == LanguageEnglish || text == "" {
		return text
	}
	for _, replacement := range settingsIntegrationReplacements {
		text = strings.ReplaceAll(text, replacement.english, T(replacement.id))
	}
	return text
}
